use vstd::prelude::*;
use vstd::string::*;

verus! {

spec fn is_ascii_letter(c: char) -> bool {
    (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

spec fn is_space(c: char) -> bool {
    c == ' '
}

fn check_if_last_char_is_a_letter(txt: &str) -> (result: bool)
    ensures
        result == (
            txt@.len() > 0 &&
            is_ascii_letter(txt@[txt@.len() - 1]) &&
            (txt@.len() == 1 || is_space(txt@[txt@.len() - 2]))
        ),
{
    // First check if string is empty
    if txt.len() == 0 {
        return false;
    }
    
    // Get the last character
    let last_char_opt = txt.chars().last();
    let last_char = match last_char_opt {
        Some(c) => c,
        None => {
            // This shouldn't happen since we checked txt.len() > 0
            // but we need to handle it for verification
            proof {
                assert(txt@.len() > 0);
            }
            return false;
        }
    };
    
    // Check if last character is ASCII letter
    if !((last_char >= 'a' && last_char <= 'z') || (last_char >= 'A' && last_char <= 'Z')) {
        return false;
    }
    
    // Check string length
    let char_count = txt.chars().count();
    
    if char_count == 1 {
        return true;
    }
    
    // Get the second-to-last character
    let mut chars_iter = txt.chars();
    let mut prev_char_opt = None;
    
    // Skip to the second-to-last character
    for _ in 0..(char_count - 2) {
        prev_char_opt = chars_iter.next();
    }
    
    let second_last_char_opt = chars_iter.next();
    let second_last_char = match second_last_char_opt {
        Some(c) => c,
        None => {
            // This shouldn't happen since char_count > 1
            proof {
                assert(char_count > 1);
            }
            return false;
        }
    };
    
    // Check if second-to-last character is space
    second_last_char == ' '
}

} // verus!

